// Blank Office templates for "New blank document" (Day 15).
//
// A blank DOCX/XLSX/PPTX is a real Office file (OOXML ZIP) made by
// python-docx / openpyxl / python-pptx. The three files live in
// src/lib/blank-templates/ and are generated by
// scripts/generate-blank-templates.py — the script is the source of
// truth, the files are not magic binaries.
//
// This module is pure and client-safe: it only lists the types and
// builds file names, so the library form can import it. The actual
// file bytes are read by src/lib/blank-templates.server.ts (which
// uses node:fs and must never be imported by a client component).
import { ALLOWED_UPLOAD_TYPES } from "@/lib/storage";

export const BLANK_TEMPLATE_TYPES = [
  { ext: "docx", label: "Document", mimeType: ALLOWED_UPLOAD_TYPES.docx },
  {
    ext: "xlsx",
    label: "Spreadsheet",
    mimeType: ALLOWED_UPLOAD_TYPES.xlsx,
  },
  {
    ext: "pptx",
    label: "Presentation",
    mimeType: ALLOWED_UPLOAD_TYPES.pptx,
  },
] as const;

export type BlankTemplateExt = (typeof BLANK_TEMPLATE_TYPES)[number]["ext"];

export function isBlankTemplateExt(ext: string): ext is BlankTemplateExt {
  return BLANK_TEMPLATE_TYPES.some((t) => t.ext === ext);
}

export function getBlankTemplateType(ext: BlankTemplateExt) {
  return BLANK_TEMPLATE_TYPES.find((t) => t.ext === ext);
}

// The file name for a document created from a template (blank or
// named): the title, sanitised, plus the extension.
export function getTemplateFileName(title: string, ext: BlankTemplateExt) {
  const base = title.trim().replace(/[^A-Za-z0-9._-]+/g, "_").replace(/^\.+/, "");
  return `${base || "Untitled"}.${ext}`;
}
